-- Módulo de productos, múltiples listas de precios, imágenes y stock.
-- Incluye la importación inicial de Producto (product.template).xlsx (323 registros).
CREATE TABLE IF NOT EXISTS product_categories (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(150) NOT NULL UNIQUE,
  active TINYINT(1) NOT NULL DEFAULT 1,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS price_lists (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(150) NOT NULL,
  currency ENUM('ARS','USD') NOT NULL,
  active TINYINT(1) NOT NULL DEFAULT 1,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY uq_price_list_name_currency(name,currency)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS products (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  category_id INT UNSIGNED NULL,
  product_type ENUM('producto','servicio','descuento') NOT NULL DEFAULT 'producto',
  sku VARCHAR(190) NULL,
  name VARCHAR(255) NOT NULL,
  description TEXT NULL,
  unit VARCHAR(60) NOT NULL DEFAULT 'Unidades',
  favorite TINYINT(1) NOT NULL DEFAULT 0,
  track_stock TINYINT(1) NOT NULL DEFAULT 1,
  stock_quantity DECIMAL(15,3) NOT NULL DEFAULT 0,
  image_data MEDIUMBLOB NULL,
  image_mime VARCHAR(60) NULL,
  source_key VARCHAR(120) NULL UNIQUE,
  source_updated_at DATETIME NULL,
  active TINYINT(1) NOT NULL DEFAULT 1,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  INDEX idx_products_name(name),
  INDEX idx_products_sku(sku),
  FOREIGN KEY(category_id) REFERENCES product_categories(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS product_prices (
  product_id INT UNSIGNED NOT NULL,
  price_list_id INT UNSIGNED NOT NULL,
  price DECIMAL(15,2) NOT NULL DEFAULT 0,
  currency ENUM('ARS','USD') NOT NULL DEFAULT 'ARS',
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY(product_id,price_list_id),
  FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE,
  FOREIGN KEY(price_list_id) REFERENCES price_lists(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS stock_movements (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  product_id INT UNSIGNED NOT NULL,
  movement_date DATE NOT NULL,
  movement_type ENUM('inicial','entrada','salida','ajuste') NOT NULL,
  quantity DECIMAL(15,3) NOT NULL,
  reference VARCHAR(190) NULL,
  notes TEXT NULL,
  user_id INT UNSIGNED NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  INDEX idx_stock_product_date(product_id,movement_date),
  FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE,
  FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


